const domain = String($json.domain || '').trim().toLowerCase();
if (domain.length > 253 || !domain.includes('.') || domain.includes('://') || domain.includes('/') || domain.includes(':') || domain.includes(' ') || domain.startsWith('.') || domain.endsWith('.') || domain.includes('..')) {
  throw new Error('Use one bare company domain, for example example.com');
}
const labels = domain.split('.');
const labelPattern = /^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$/;
if (labels.some((label) => label.length < 1 || label.length > 63 || !labelPattern.test(label)) || !/^[A-Za-z]{2,63}$/.test(labels.at(-1))) {
  throw new Error('The company domain is invalid');
}
return [{ json: { domain, integrationSource: 'n8n-github-c9' } }];

const expectedDomain = $('Validate domain').first().json.domain;
const rows = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
if (rows.length !== 1) {
  throw new Error('Expected exactly one company metadata result');
}
const row = rows[0];
if (row.success !== true || row.domain !== expectedDomain || row.integrationSource !== 'n8n-github-c9' || row.provenance?.method !== 'website_metadata_scrape') {
  throw new Error('The Actor response failed semantic validation');
}
return [{ json: row }];
